package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: n headId manager array then informTime array, for example: 6 2 [2,2,-1,2,2,2] [0,0,1,0,0,0]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ",args).trim()); return;} assertThat(Solution.minutesToInformAll(1,0,new int[]{-1},new int[]{0})).as("Example 1").isZero(); assertThat(Solution.minutesToInformAll(6,2,new int[]{2,2,-1,2,2,2},new int[]{0,0,1,0,0,0})).as("Example 2").isEqualTo(1); assertThat(Solution.minutesToInformAll(7,6,new int[]{1,2,3,4,5,6,-1},new int[]{0,6,5,4,3,2,1})).as("Example 3").isEqualTo(21); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ int b1=input.indexOf('['), e1=input.indexOf(']',b1), b2=input.indexOf('[',e1), e2=input.indexOf(']',b2); String[] h=input.substring(0,b1).trim().split("\s+"); int n=Integer.parseInt(h[0]), head=Integer.parseInt(h[1]); int[] m=parse(input.substring(b1,e1+1)), t=parse(input.substring(b2,e2+1)); System.out.println("minutesToInformAll = "+Solution.minutesToInformAll(n,head,m,t)); }catch(RuntimeException e){ System.out.println("Could not read input. "+USAGE); } } private static int[] parse(String s){ String c=s.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\s+")).mapToInt(Integer::parseInt).toArray(); } }
